def generate(rng):
    sectors = ['manufacturero', 'industrial', 'agrícola', 'tecnológico', 'de bienes de capital', 'energético', 'textil', 'automotriz', 'químico', 'metalúrgico']
    sector = rng.choice(sectors)
    n_pct = rng.randint(1, 6)
    opts = [
        {
            'content': 'La tasa de crecimiento de la fuerza de trabajo $n$ es un parámetro estrictamente exógeno y constante en el modelo neoclásico de Solow.',
            'is_correct': True,
            'distractor_id': None
        },
        {
            'content': 'Las fluctuaciones en el salario real o en el ingreso por habitante no alteran la trayectoria demográfica $L(t) = L_0 e^{nt}$.',
            'is_correct': True,
            'distractor_id': None
        },
        {
            'content': f'La tasa de crecimiento de la población se acelera por encima del {n_pct}% cuando los salarios reales superan el nivel biológico de subsistencia.',
            'is_correct': False,
            'distractor_id': 'D-C06-01',
            'error_rationale': 'En el modelo básico de Solow, el crecimiento demográfico es estrictamente exógeno a tasa n y no responde a dinámicas endógenas clásicas o malthusianas de subsistencia.'
        },
        {
            'content': f'Si el ingreso medio cae temporalmente por debajo del costo de vida, la tasa demográfica del {n_pct}% frena a cero para restablecer el equilibrio malthusiano.',
            'is_correct': False,
            'distractor_id': 'D-C06-01',
            'error_rationale': 'El modelo no incorpora frenos malthusianos preventivos o positivos; la oferta de trabajo continúa expandiéndose a la tasa exógena constante n.'
        }
    ]
    return {
        'vars': {'sector': sector, 'n_pct': n_pct},
        'options': opts,
        'distractors': []
    }

def generate(rng):
