    alpha_pct = rng.randint(25, 45)
    opts = [
        {
            'content': 'La oferta de mano de obra es perfectamente inelástica en cada instante, ofreciéndose la totalidad de los trabajadores disponibles sin importar el salario real.',
            'is_correct': True,
            'distractor_id': None
        },
        {
            'content': 'La flexibilidad instantánea y perfecta del salario real, igualándose a la productividad marginal $\\partial F / \\partial L$, asegura el vaciado continuo del mercado y el pleno empleo permanente.',
            'is_correct': True,
            'distractor_id': None
        },
        {
            'content': f'Dado que la oferta de trabajo es totalmente inelástica, se genera desempleo estructural permanente si las empresas demandan menos del {alpha_pct}% del producto agregado.',
            'is_correct': False,
            'distractor_id': 'D-C06-02',
            'error_rationale': 'El salario real es perfectamente flexible y se ajusta continuamente para igualar la demanda de trabajo a la oferta inelástica, garantizando el pleno empleo en todo momento sin desempleo involuntario.'
