def generate(rng):
    regions = ['norte', 'sur', 'central', 'oriental', 'occidental', 'costera', 'metropolitana', 'fronteriza', 'andina', 'rural']
    region = rng.choice(regions)
    year_t = rng.randint(5, 40)
    opts = [
        {
            'content': 'Durante la transición fuera del estado estacionario, el capital se acumula a la tasa $\\dot{K}/K = s F(K, L)/K$, la cual difiere de la tasa de crecimiento demográfico $n$.',
            'is_correct': True,
            'distractor_id': None
        },
        {
            'content': 'La tasa de crecimiento del stock de capital solo converge e iguala a la tasa poblacional $n$ cuando la relación capital-trabajo alcanza su valor de estado estacionario.',
            'is_correct': True,
            'distractor_id': None
        },
        {
            'content': f'El supuesto de pleno empleo perpetuo obliga a que el stock de capital físico crezca obligatoriamente a la tasa demográfica $n$ en el año {year_t} de transición.',
            'is_correct': False,
            'distractor_id': 'D-C06-03',
            'error_rationale': 'La tasa n es la tasa de crecimiento de la mano de obra; durante la transición el capital crece a tasa s F(K, L)/K, la cual es diferente de n mientras la intensidad de capital se ajusta dinámicamente.'
        },
        {
            'content': f'Fuera del estado estacionario, tras {year_t} años de ajuste, el capital y el trabajo deben expandirse siempre a una tasa idéntica para evitar crisis de sobreacumulación.',
            'is_correct': False,
            'distractor_id': 'D-C06-03',
            'error_rationale': 'El ajuste hacia el estado estacionario ocurre precisamente porque el capital y el trabajo crecen a ritmos diferentes, permitiendo que la intensidad de capital r varíe hacia su valor de equilibrio.'
        }
    ]
    return {
        'vars': {'region': region, 'year_t': year_t},
        'options': opts,
        'distractors': []
    }
